def authorize(policy, action):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kw):
            ctx = security_context()                  # set by auth middleware
            decision = policy.decide(ctx, action, kw['document'])
            if not decision.allow:                    # deny by default
                raise AccessDenied(decision.reason)
            return fn(*args, **kw)
        return wrapper
    return deco

